// dsh-control-panel — 总控台客户端。
//
// 在 DSH 左侧栏加一个「总控台」入口，点进去是 3 个 Agent（记忆 / 代码 / 生活）
// 的实时状态面板：每张卡片显示该 Agent 是工作中还是空闲、正在干什么（实时输出
// 预览）、最近一次活动时间；点击卡片或「进入对话」直接打开该 Agent 的对话框。
//
// 实现走 DSH 官方客户端 API（0.2.2-rc.1 实测源码核对）：
//   - 主面板 + 左侧栏入口：ctx.slots.inject("main") / ("sidebar.panellist")
//     （日程、插件管理同款机制）
//   - 会话列表实时快照：ctx.sessions.list（running / title / updatedAt）
//   - 实时输出预览：ctx.sessions.retain + projections.faceOf("turnOutline").draft
//   - 进入对话：ctx.uiWorkspace.openSession(sessionId)
//   - 面板切换：ctx.layout.selectPanel(null) 回到对话
//
// 注意：client 侧只能 require("react")；不要按包内路径取资源、不要相对 require。
// 样式用 DSH 设计 token + 与桌面端毛玻璃同款的半透明卡片，不与 QQ 渐变背景冲突。
window.__ModuleLoader__.load({
  id: "dsh-control-panel",
  factory: (require) => {
    var module = { exports: {} };
    var exports = module.exports;
    Object.defineProperty(exports, Symbol.toStringTag, { value: "Module" });
    let react = require("react");

    const NS = "control-panel";
    const PANEL_ID = "control-panel";

    // 3 个 Agent：sessionId 与 dsh-home/sessions 下的目录名、Telegram 桥的
    // AGENTS 表一致。general 是兜底，不进总控台（用户只点了 3 个）。
    // 头像：内嵌 base64（client 侧不能按包内路径取资源）。
    // 记忆 = Nous Research Hermes Agent 官方应用图标（github.com/NousResearch/hermes-agent website/static/img/logo.png；另见 hermes-agent.nousresearch.com/icon.png）。
    // 代码 = Anthropic Claude 官方 Clawd 吉祥物（claude.ai/images/clawd.svg，按官方 SVG 路径重绘）。
    // 生活 = Muse 元神正面图（按用户提供的参考照片生成，正面、端正）。
    const AVATAR_MEMORY = "data:image/png;base64,";
    const AVATAR_CODE = "data:image/png;base64,";
    const AVATAR_LIFE = "data:image/png;base64,";

    const AGENTS = [
      { id: "memory", zh: "记忆", en: "Memory", roleZh: "长期记忆与知识管理", roleEn: "Long-term memory & knowledge", accent: "#7c8cff", avatar: AVATAR_MEMORY },
      { id: "code", zh: "代码", en: "Code", roleZh: "写代码、审查与调试", roleEn: "Write, review & debug code", accent: "#34d399", avatar: AVATAR_CODE },
      { id: "life", zh: "生活", en: "Life", roleZh: "日常琐事与生活助手", roleEn: "Daily life assistant", accent: "#fbbf24", avatar: AVATAR_LIFE },
    ];

    const zh = {
      panel: "总控台",
      title: "总控台",
      subtitle: "3 个 Agent 的实时状态，点一张卡片直接进入它的对话。",
      working: "工作中",
      idle: "空闲",
      unavailable: "未连接",
      notFound: "会话不存在",
      doingNow: "正在干什么",
      outputting: "正在输出",
      thinking: "正在思考 / 调用工具中…",
      lastTurn: "上次",
      noActivity: "暂无进行中的任务",
      noTitle: "暂无标题",
      lastActive: "最后活动",
      justNow: "刚刚",
      minutesAgo: "{n} 分钟前",
      hoursAgo: "{n} 小时前",
      daysAgo: "{n} 天前",
      enter: "进入对话",
      openFailed: "打开会话失败",
      liveNote: "状态实时更新；输出预览只在 Agent 工作时出现。",
    };

    const en = {
      panel: "Control Panel",
      title: "Control Panel",
      subtitle: "Live status of your 3 agents — click a card to open its conversation.",
      working: "Working",
      idle: "Idle",
      unavailable: "Offline",
      notFound: "Session not found",
      doingNow: "Doing now",
      outputting: "Outputting",
      thinking: "Thinking / calling tools…",
      lastTurn: "Last",
      noActivity: "No active task",
      noTitle: "No title yet",
      lastActive: "Last active",
      justNow: "just now",
      minutesAgo: "{n} min ago",
      hoursAgo: "{n} h ago",
      daysAgo: "{n} d ago",
      enter: "Open conversation",
      openFailed: "Failed to open session",
      liveNote: "Status updates live; the output preview only shows while an agent is working.",
    };

    // ---- 小工具 ----
    function truncate(text, max) {
      if (!text) return "";
      const s = String(text).replace(/\s+/g, " ").trim();
      return s.length > max ? s.slice(0, max) + "…" : s;
    }

    function formatRelative(t, at, now) {
      if (!at) return "";
      const diff = Math.max(0, now - at);
      const min = Math.floor(diff / 60000);
      if (min < 1) return t("justNow");
      if (min < 60) return t("minutesAgo").replace("{n}", String(min));
      const h = Math.floor(min / 60);
      if (h < 24) return t("hoursAgo").replace("{n}", String(h));
      const d = Math.floor(h / 24);
      return t("daysAgo").replace("{n}", String(d));
    }

    function sessionTitle(row) {
      if (!row) return "";
      const pv = row.projectionValues;
      if (pv && typeof pv.title === "string" && pv.title) return pv.title;
      const hints = row.projections && row.projections.values;
      if (hints && typeof hints.title === "string" && hints.title) return hints.title;
      return "";
    }

    // ---- 左侧栏图标：2x2 仪表盘 ----
    function ControlPanelIcon(props) {
      return react.createElement("svg", {
        width: "18", height: "18", viewBox: "0 0 18 18", fill: "none",
        "aria-hidden": "true", focusable: "false",
        style: { display: "block", flex: "none" },
        ...(props || {}),
      }, [
        react.createElement("rect", { key: "a", x: "1.5", y: "1.5", width: "6.5", height: "6.5", rx: "1.5", stroke: "currentColor", strokeWidth: "1.4" }),
        react.createElement("rect", { key: "b", x: "10", y: "1.5", width: "6.5", height: "6.5", rx: "1.5", stroke: "currentColor", strokeWidth: "1.4" }),
        react.createElement("rect", { key: "c", x: "1.5", y: "10", width: "6.5", height: "6.5", rx: "1.5", stroke: "currentColor", strokeWidth: "1.4" }),
        react.createElement("circle", { key: "d", cx: "13.25", cy: "13.25", r: "2.6", fill: "currentColor" }),
      ]);
    }

    // ---- 会话列表快照（实时） ----
    function useSessionList(ctx) {
      const store = ctx.sessions.list;
      return react.useSyncExternalStore(
        (cb) => store.subscribe(cb),
        () => store.getSnapshot()
      );
    }

    // ---- 单个 Agent 的实时输出预览（turnOutline.draft） ----
    // 面板打开时 retain 该会话，读它的 turnOutline 投影；关闭时释放。
    // 任何一步失败都静默降级为只显示列表数据（running / title / updatedAt）。
    function useAgentOutline(ctx, sessionId) {
      const [outline, setOutline] = react.useState(null);
      react.useEffect(() => {
        let cancelled = false;
        let ref = null;
        let unsub = null;
        try {
          ref = ctx.sessions.retain(sessionId, { source: "control-panel" });
        } catch (e) {
          return undefined;
        }
        ref.ready.then(() => {
          if (cancelled) return;
          try {
            const face = ref.binding.session.projections.faceOf("turnOutline");
            const update = () => {
              try {
                const v = face.getSnapshot();
                if (v && typeof v === "object") setOutline(v);
              } catch (e) { /* 忽略单次读取失败 */ }
            };
            update();
            unsub = face.subscribe(update);
          } catch (e) { /* 降级：无实时预览 */ }
        }).catch(() => { /* 会话打不开时降级 */ });
        return () => {
          cancelled = true;
          try { if (unsub) unsub(); } catch (e) {}
          try { if (ref) ref.release(); } catch (e) {}
        };
      }, [sessionId]);
      return outline;
    }

    // ---- 样式（与桌面端毛玻璃同款，半透明深色卡片 + 白字） ----
    const styles = {
      page: {
        display: "flex", flexDirection: "column", minHeight: "100%",
        padding: "28px 32px 32px", boxSizing: "border-box",
        color: "rgba(255,255,255,0.95)", overflowY: "auto",
      },
      header: { marginBottom: "20px" },
      h1: { margin: "0 0 6px", fontSize: "24px", lineHeight: "1.3", fontWeight: 700, color: "rgba(255,255,255,0.96)", textShadow: "0 1px 3px rgba(15,23,42,0.35)" },
      sub: { margin: 0, fontSize: "13px", lineHeight: "1.6", color: "rgba(255,255,255,0.72)", textShadow: "0 1px 2px rgba(15,23,42,0.35)" },
      grid: {
        display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
        gap: "16px", alignItems: "start",
      },
      card: {
        display: "flex", flexDirection: "column", gap: "10px",
        padding: "16px 18px", borderRadius: "16px", cursor: "pointer",
        background: "rgba(15,23,42,0.45)",
        backdropFilter: "blur(16px) saturate(1.3)",
        WebkitBackdropFilter: "blur(16px) saturate(1.3)",
        border: "1px solid rgba(255,255,255,0.18)",
        boxShadow: "0 8px 24px rgba(0,0,0,0.25), inset 0 1px 0 rgba(255,255,255,0.12)",
        transition: "border-color 120ms ease, transform 120ms ease",
      },
      cardTop: { display: "flex", alignItems: "center", gap: "10px" },
      avatar: {
        width: "36px", height: "36px", borderRadius: "10px", flex: "none",
        display: "block", objectFit: "cover",
      },
      nameWrap: { flex: "1 1 auto", minWidth: 0 },
      name: { fontSize: "16px", fontWeight: 700, lineHeight: "1.3", color: "rgba(255,255,255,0.96)" },
      role: { fontSize: "12px", lineHeight: "1.4", color: "rgba(255,255,255,0.65)", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" },
      pill: {
        flex: "none", display: "inline-flex", alignItems: "center", gap: "6px",
        fontSize: "12px", fontWeight: 600, lineHeight: "1",
        padding: "6px 10px", borderRadius: "999px",
        border: "1px solid rgba(255,255,255,0.25)",
      },
      dot: { width: "8px", height: "8px", borderRadius: "50%", flex: "none" },
      titleLine: { fontSize: "13px", lineHeight: "1.5", color: "rgba(255,255,255,0.85)", overflow: "hidden", display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical" },
      activityBox: {
        fontSize: "13px", lineHeight: "1.65", color: "rgba(255,255,255,0.82)",
        background: "rgba(255,255,255,0.07)", border: "1px solid rgba(255,255,255,0.10)",
        borderRadius: "10px", padding: "10px 12px", minHeight: "64px",
        overflow: "hidden", display: "-webkit-box", WebkitLineClamp: 4, WebkitBoxOrient: "vertical",
        whiteSpace: "pre-wrap", wordBreak: "break-word",
      },
      activityLabel: { fontSize: "11px", fontWeight: 700, letterSpacing: "0.04em", color: "rgba(255,255,255,0.55)", marginBottom: "4px" },
      foot: { display: "flex", alignItems: "center", gap: "10px" },
      lastActive: { flex: "1 1 auto", fontSize: "12px", color: "rgba(255,255,255,0.55)", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" },
      enterBtn: {
        flex: "none", cursor: "pointer", fontSize: "13px", fontWeight: 600,
        color: "rgba(15,23,42,0.92)", background: "rgba(255,255,255,0.85)",
        border: "1px solid rgba(255,255,255,0.6)", borderRadius: "999px",
        padding: "7px 14px",
      },
      note: { marginTop: "20px", fontSize: "12px", color: "rgba(255,255,255,0.5)", textShadow: "0 1px 2px rgba(15,23,42,0.35)" },
    };

    // ---- 单张 Agent 卡片 ----
    function AgentCard(props) {
      const ctx = props.ctx;
      const agent = props.agent;
      const t = props.t;
      const now = props.now;
      const row = props.row;
      const outline = useAgentOutline(ctx, agent.id);

      const running = !!(row && row.running);
      const available = !row || row.agentAvailable !== false;
      const title = sessionTitle(row);
      const draft = outline && typeof outline.draft === "string" ? outline.draft : "";
      const turns = outline && Array.isArray(outline.turns) ? outline.turns : [];
      const lastTurn = turns.length > 0 ? turns[turns.length - 1] : null;
      const lastText = lastTurn
        ? (lastTurn.response || lastTurn.prompt || "")
        : "";

      let statusText;
      let dotColor;
      let pillBg;
      if (!row) { statusText = t("notFound"); dotColor = "#94a3b8"; pillBg = "rgba(148,163,184,0.18)"; }
      else if (!available) { statusText = t("unavailable"); dotColor = "#94a3b8"; pillBg = "rgba(148,163,184,0.18)"; }
      else if (running) { statusText = t("working"); dotColor = "#34d399"; pillBg = "rgba(52,211,153,0.20)"; }
      else { statusText = t("idle"); dotColor = "#94a3b8"; pillBg = "rgba(148,163,184,0.18)"; }

      let activityLabel;
      let activityText;
      if (running && draft) { activityLabel = t("outputting"); activityText = truncate(draft, 400); }
      else if (running) { activityLabel = t("doingNow"); activityText = t("thinking"); }
      else if (lastText) { activityLabel = t("lastTurn"); activityText = truncate(lastText, 400); }
      else { activityLabel = t("doingNow"); activityText = t("noActivity"); }

      const lastActiveText = row && row.updatedAt
        ? t("lastActive") + " " + formatRelative(t, row.updatedAt, now)
        : "";

      const open = () => {
        try {
          ctx.uiWorkspace.openSession(agent.id);
        } catch (e) {
          try { ctx.layout.selectPanel(null); } catch (e2) {}
        }
      };

      return react.createElement("div", {
        style: styles.card,
        onClick: open,
        onMouseEnter: (e) => { e.currentTarget.style.borderColor = "rgba(255,255,255,0.38)"; },
        onMouseLeave: (e) => { e.currentTarget.style.borderColor = "rgba(255,255,255,0.18)"; },
        role: "button",
        tabIndex: 0,
        onKeyDown: (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); open(); } },
        "aria-label": agent.zh + " " + statusText,
      }, [
        react.createElement("div", { key: "top", style: styles.cardTop }, [
          react.createElement("img", { key: "av", src: agent.avatar, alt: agent.zh, style: styles.avatar }),
          react.createElement("div", { key: "nm", style: styles.nameWrap }, [
            react.createElement("div", { key: "n", style: styles.name }, agent.zh + " · " + agent.en),
            react.createElement("div", { key: "r", style: styles.role }, agent.roleZh),
          ]),
          react.createElement("span", { key: "pill", style: { ...styles.pill, background: pillBg } }, [
            react.createElement("span", { key: "dot", style: { ...styles.dot, background: dotColor } }),
            statusText,
          ]),
        ]),
        react.createElement("div", { key: "title", style: styles.titleLine }, title || t("noTitle")),
        react.createElement("div", { key: "act", style: styles.activityBox }, [
          react.createElement("div", { key: "lb", style: styles.activityLabel }, activityLabel),
          activityText,
        ]),
        react.createElement("div", { key: "foot", style: styles.foot }, [
          react.createElement("span", { key: "la", style: styles.lastActive }, lastActiveText),
          react.createElement("button", {
            key: "btn", type: "button", style: styles.enterBtn,
            onClick: (e) => { e.stopPropagation(); open(); },
          }, t("enter") + " →"),
        ]),
      ]);
    }

    // ---- 总控台主页面 ----
    function ControlPanelPage(props) {
      const ctx = props.ctx;
      const t = ctx.locale.bind(NS);
      const list = useSessionList(ctx);
      const [now, setNow] = react.useState(Date.now());
      react.useEffect(() => {
        const timer = setInterval(() => setNow(Date.now()), 30000);
        return () => clearInterval(timer);
      }, []);

      const byId = (list && list.byId) || {};
      return react.createElement("div", { style: styles.page }, [
        react.createElement("div", { key: "hd", style: styles.header }, [
          react.createElement("h1", { key: "h", style: styles.h1 }, t("title")),
          react.createElement("p", { key: "s", style: styles.sub }, t("subtitle")),
        ]),
        react.createElement("div", { key: "grid", style: styles.grid },
          AGENTS.map((agent) =>
            react.createElement(AgentCard, {
              key: agent.id, ctx, agent, t, now,
              row: byId[agent.id] || null,
            })
          )
        ),
        react.createElement("div", { key: "note", style: styles.note }, t("liveNote")),
      ]);
    }

    function apply(ctx) {
      ctx.effect(() => ctx.locale.register(NS, { zh, en }), "control-panel: dictionaries");
      const t = ctx.locale.bind(NS);
      // 主面板：中央区域的总控台页面（日程、插件管理同款机制）。
      ctx.slots.inject("main", () => ctx.slots.register({
        name: "main",
        key: PANEL_ID,
        locale: NS,
        inject: () => ({ ctx }),
      }, ControlPanelPage));
      // 左侧栏入口：点一下打开总控台。
      ctx.slots.inject("sidebar.panellist", () => ctx.slots.register({
        name: "sidebar.panellist",
        id: PANEL_ID,
        order: 1,
        locale: NS,
        label: () => t("panel"),
      }, ControlPanelIcon));
    }

    exports.apply = apply;
    exports.inject = ["slots", "locale", "sessions", "layout", "uiWorkspace"];
    return module.exports;
  }
});
